reactor.deferStart=true;
const state={tracks:[],playlists:[],token:'',view:'home',query:'',genre:'',sort:'youtube',limit:80,current:null,queue:[],shuffle:false,repeat:0,session:'',listened:0,pendingSeconds:0,lastTick:0,status:{},syncPreview:null,dialog:'',eq:[0,0,0],artist:'',refreshBusy:false,prefs:{},playGeneration:0,loadHandler:null};
const playQueue=new ContinuousQueue(()=>state.tracks);
const getTrack=id=>state.tracks.find(t=>t.id===id);
async function api(url,body,method){const r=await fetch(url,{method:method||(body?'POST':'GET'),headers:body?{'Content-Type':'application/json','X-Resonance-Token':state.token}:{},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');return d;}
installSettingResets({state,setPreferences,onEQ:(index)=>{state.eq[index]=0;reactor.eq(state.eq);soundDialog();}});
const artworkPalette=new ArtworkPalette({read:artwork=>api('/api/artwork-palette?artwork='+encodeURIComponent(artwork)),write:(artwork,colors)=>api('/api/artwork-palette',{artwork,colors}),decode:decodeArtwork,onChange:(colors,status)=>{reactor.coverColors=colors;reactor.coverStatus=status;applyInterfaceAccent(document.body.classList.contains('desktop-listening')?null:colors,state.prefs.coverInterface!==false);reactor.needsFrame=true;}});
const toast=message=>{const e=document.createElement('div');e.className='toast';e.textContent=message;$('#toasts').append(e);setTimeout(()=>e.remove(),5000);};
const safe=fn=>(...args)=>{try{return Promise.resolve(fn(...args)).catch(e=>toast(e.message));}catch(e){toast(e.message);}};
function art(t){if(t?.artwork)return `<img class="cover-image" src="/artwork/${encodeURIComponent(t.artwork)}" alt="${esc(t.title)} artwork" loading="lazy">`;const hue=t?parseInt(t.id.slice(0,4),16)%100+230:267;return `<div class="cover-placeholder" style="--hue:${hue}" role="img" aria-label="Artwork not yet available"><span>${t?.kind==='mix'?'MIX':'R'}</span></div>`;}
function quality(t){return `${t.codec||'Audio'}${t.sampleRate?` · ${t.sampleRate/1000} kHz`:''}${t.bits?` · ${t.bits} bit`:''}`;}
async function refresh(render=true){if(state.refreshBusy)return;state.refreshBusy=true;try{const d=await api('/api/library');state.tracks=d.tracks;state.playlists=d.playlists;state.config=d.config;state.capabilities=d.capabilities;state.token=d.token;if(state.current)state.current=getTrack(state.current.id)||state.current;renderSidebar();if(render)renderMain();renderNow();return d;}finally{state.refreshBusy=false;}}
function renderSidebar(){sourceUI.renderNav();$('#track-count').textContent=state.tracks.filter(t=>t.kind==='track'&&t.available).length.toLocaleString();$('#mix-count').textContent=state.tracks.filter(t=>t.kind==='mix'&&t.available).length;$('#playlists-nav').innerHTML=state.playlists.map(p=>`<button class="nav-item ${state.view===`playlist:${p.id}`?'active':''}" data-view="playlist:${p.id}">${icon('music')}<span>${esc(p.name)}</span><span class="nav-count">${p.tracks.length}</span></button>`).join('')||'<p class="fine-print" style="padding:0 12px">Make a home for a mood.</p>';$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));$('#library-status').textContent=`${state.tracks.filter(t=>t.available).length.toLocaleString()} sounds, stored locally`;}
const names={home:'Listen now',tracks:'All tracks',mixes:'Long mixes',favorites:'Favorites',recent:'Recently played',artists:'Artists',genres:'Explore genres',settings:'Settings & library',artist:'Artist'};
function navigate(view){state.view=view;state.limit=80;state.genre='';state.query='';$('#search').value='';renderSidebar();renderMain();$('#main').scrollTop=0;if(feedback.motion)$('#main').animate([{opacity:.65,transform:'translateY(5px)'},{opacity:1,transform:'translateY(0)'}],{duration:180,easing:'ease-out'});}
function filtered(){let ts=state.tracks.filter(t=>t.available);if(state.view==='mixes')ts=ts.filter(t=>t.kind==='mix');if(state.view==='tracks')ts=ts.filter(t=>t.kind==='track');if(state.view==='favorites')ts=ts.filter(t=>t.favorite);if(state.view==='recent')ts=ts.filter(t=>t.lastPlayed);if(state.view==='artist')ts=ts.filter(t=>hasArtist(t,state.artist));if(state.view.startsWith('playlist:')){const ids=state.playlists.find(p=>`playlist:${p.id}`===state.view)?.tracks||[];ts=ids.map(getTrack).filter(t=>t?.available);}if(state.view.startsWith('source:')){const s=state.config.sources.find(s=>'source:'+s.id===state.view);ts=s?.trackIds?s.trackIds.map(getTrack).filter(t=>t?.available):ts.filter(t=>t.sourceId===s?.id);}if(state.prefs.artistGenres===false)ts=ts.filter(t=>t.genreBasis!=='artist'||!state.genre);if(state.genre==='__unknown')ts=ts.filter(t=>!t.genre);else if(state.genre)ts=ts.filter(t=>genreNames(t).some(g=>g.toLowerCase()===state.genre.toLowerCase()));if(state.query){const fold=s=>s.normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase();const words=fold(state.query).split(/\s+/).filter(Boolean);ts=ts.filter(t=>words.every(q=>fold(`${t.title} ${t.artist} ${t.album} ${t.genre} ${t.rawTitle} ${t.channel||''}`).includes(q)));}const sort=state.view==='recent'?'recent':state.sort;const source=state.config?.sources.find(s=>'source:'+s.id===state.view);const order=source&&!source.playlist?new Map(source.trackIds?.map((id,i)=>[id,i])):null;return ts.sort((a,b)=>sort==='youtube'?(order?(order.get(a.id)??Infinity)-(order.get(b.id)??Infinity):youtubeOrder(a,b,state.config?.sources)):sort==='plays'?b.plays-a.plays:sort==='recent'?b.lastPlayed-a.lastPlayed:sort==='added'?b.addedAt-a.addedAt:sort==='duration'?b.duration-a.duration:sort==='artist'?a.artist.localeCompare(b.artist):a.title.localeCompare(b.title));}
function card(t){return `<article class="music-card"><button class="cover-button" data-play="${t.id}" aria-label="Play ${esc(t.title)}">${art(t)}${t.kind==='mix'?`<span class="cover-duration">${duration(t.duration)}</span>`:''}<span class="cover-play">${icon('play')}</span></button><div class="card-meta"><div style="min-width:0"><h3 title="${esc(t.title)}">${esc(t.title)}</h3><p>${esc(t.artist||t.channel||'Artist to discover')}</p></div><button class="icon-button" data-detail="${t.id}" title="Track details" aria-label="Details for ${esc(t.title)}">${icon('more')}</button></div></article>`;}
function table(ts,max=state.limit){if(!ts.length)return '<div class="empty-state"><h2>Room for a new favorite.</h2><p>Try another search, or explore your library.</p></div>';return `<table class="track-table"><thead><tr><th>#</th><th>TRACK</th><th>ALBUM / SOURCE</th><th>FORMAT</th><th>TIME</th><th></th></tr></thead><tbody>${ts.slice(0,max).map((t,i)=>`<tr class="${state.current?.id===t.id?'playing':''}"><td>${state.current?.id===t.id?icon('waves'):state.sort==='youtube'&&state.config.sources.some(s=>s.playlist)&&!(state.view.startsWith('source:')&&!state.config.sources.find(s=>'source:'+s.id===state.view)?.playlist)?(t.playlistIndex?String(t.playlistIndex).padStart(2,'0'):'—'):String(i+1).padStart(2,'0')}</td><td><button class="track-cell" data-play="${t.id}" title="Play ${esc(t.title)}"><div class="track-thumb">${art(t)}</div><span class="track-info"><b>${esc(t.title)}</b><small>${esc(t.artist||t.channel||'Artist to discover')}${!t.available?' · File unavailable':''}</small></span></button></td><td class="table-album">${esc(t.album||t.channel||(t.kind==='mix'?'Long mixes':'Your collection'))}${t.genre?`<small class="row-genre" title="${t.genreBasis==='artist'?'Suggested from artist':'Track genre'}">${t.genreBasis==='artist'?'≈ ':''}${esc(t.genre)}</small>`:''}</td><td><span class="format-pill">${esc((t.codec||'audio').split('/')[0])}</span></td><td>${duration(t.duration)}</td><td><div class="row-actions"><button class="icon-button ${t.favorite?'active':''}" data-favorite="${t.id}" aria-label="${t.favorite?'Unfavorite':'Favorite'} ${esc(t.title)}" title="Favorite">${icon('heart')}</button><button class="icon-button" data-detail="${t.id}" aria-label="Details for ${esc(t.title)}" title="Track details">${icon('more')}</button></div></td></tr>`).join('')}</tbody></table>`;}
function renderMain(){const root=$('#main'),key=[state.view,state.query,state.genre,state.sort].join('|'),restore=rememberView(root);const same=state.mainViewKey===key;state.mainViewKey=key;paintMain();if(same)restore();else root.scrollTop=0;}
function paintMain(){const ts=filtered();let title=names[state.view]||state.config?.sources.find(s=>'source:'+s.id===state.view)?.name||state.playlists.find(p=>`playlist:${p.id}`===state.view)?.name||'Your music';if(state.view==='artist')title=state.artist;if(state.query)title=`Results for “${state.query}”`;$('#breadcrumb').textContent=title;
  if(state.view==='settings'&&!state.query){renderSettings();mountStorage(document.querySelector('.storage-card'),api);appendPreferences();return;}
  if(state.view==='genres'&&!state.query){renderGenres();return;}
  if(!state.tracks.some(t=>t.available)){$('#main').innerHTML=`<div class="page-heading"><div class="eyebrow">WELCOME TO RESONANCE</div></div><div class="empty-state"><h2>${state.config.sources.length?'Your music is moving in.':'Make room for your music.'}</h2><p>${state.config.sources.length?'Your connected sources are indexed locally. Rescan if you have added more files.':'Bring a music folder, a YouTube or public Spotify playlist, or a local playlist.'}</p><button class="primary" data-source-add>Add music source</button>${state.config.sources.length?'<button class="secondary" data-action="scan">Rescan sources</button>':''}</div>`;return;}
  let content=`<div class="page-heading"><div><div class="eyebrow">${state.view==='home'&&!state.query?'A SPACE TO JUST LISTEN':'THE SOUND OF YOU'}</div><h1>${esc(title)}</h1>${state.view==='home'&&!state.query?'<p>Good music. No noise. Just you.</p>':`<p>${ts.length.toLocaleString()} ${state.view==='mixes'?'mixes':'tracks'} · ${humanHours(ts.reduce((s,t)=>s+t.duration,0))} of sound</p>`}</div><div>${state.view==='home'&&!state.query?`<span class="date-note">${new Date().toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'})}</span>`:`<button class="primary" data-action="play-all">${icon('play')} Play all</button>${state.view.startsWith('playlist:')?'<button class="icon-button delete-playlist" data-action="edit-playlist" title="Edit playlist" aria-label="Edit playlist">'+icon('sliders')+'</button>':''}`}</div></div>`;
  if(state.view==='home'&&!state.query){
    const picks=state.tracks.filter(t=>t.available&&t.kind==='track').sort((a,b)=>Number(!!b.artwork)-Number(!!a.artwork)||b.lastPlayed-a.lastPlayed||a.id.localeCompare(b.id)).slice(0,6);
    const mixes=state.tracks.filter(t=>t.available&&t.kind==='mix').sort((a,b)=>b.lastPlayed-a.lastPlayed||Number(!!b.artwork)-Number(!!a.artwork)||a.id.localeCompare(b.id)).slice(0,6);
    const recent=state.tracks.filter(t=>t.lastPlayed).sort((a,b)=>b.lastPlayed-a.lastPlayed);
    content+=`<section class="hero"><canvas data-reactor="hero" aria-label="Audio reactive orbital visualizer"></canvas><div class="hero-copy"><div class="eyebrow"><span class="live-dot"></span> TUNE EVERYTHING ELSE OUT</div><h2>A little louder.<br><em>A little closer.</em></h2><p>Your whole world of music, in one place.<br>Find a feeling. Stay a while.</p><div class="hero-actions"><button class="primary" data-action="surprise">${icon('play')} Find my frequency</button><button class="text-button" data-action="room">Open listening room ↗</button></div></div><div class="hero-label">SOUND IN MOTION<span>LIVE AUDIO REACTIVE VISUALS</span></div></section>`;
    content+=`<section><div class="section-heading"><div><h2>Made for your ears</h2><p>Rediscover something in your collection.</p></div><button class="text-button" data-view="tracks">Explore all tracks ↗</button></div><div class="card-grid">${picks.map(card).join('')}</div></section>`;
    content+=`<section><div class="section-heading"><div><h2>${recent.length?'Back in rotation':'Take something for a spin'}</h2><p>${recent.length?'The sounds you keep coming back to.':'Press play. Your listening history starts here.'}</p></div><button class="text-button" data-view="${recent.length?'recent':'tracks'}">View all ↗</button></div>${table(recent.length?recent:ts.slice().sort((a,b)=>Number(!!b.artwork)-Number(!!a.artwork)),6)}</section>`;
    content+=`<section style="margin-top:30px"><div class="section-heading"><div><h2>Stay a little longer</h2><p>Long mixes. Uninterrupted moods. Pick up where you left off.</p></div><button class="text-button" data-view="mixes">Explore mixes ↗</button></div><div class="card-grid">${mixes.map(card).join('')}</div></section>`;
  }else if(state.view==='artists'&&!state.query){const artists=new Map();for(const t of ts)for(const name of artistNames(t)){if(!artists.has(name))artists.set(name,[]);artists.get(name).push(t);}content+=`<div class="artist-grid">${[...artists].sort((a,b)=>b[1].length-a[1].length).slice(0,state.limit).map(([artist,tracks])=>`<button class="artist-card" data-artist="${esc(artist)}"><div class="artist-art">${art(tracks.find(t=>t.artwork)||tracks[0])}</div><h3>${esc(artist)}</h3><p>${tracks.length} tracks</p></button>`).join('')}</div>`;if(artists.size>state.limit)content+='<div class="load-more"><button class="secondary" data-action="more">Show more artists</button></div>';
  }else{const genres=genreCounts().map(([name])=>name);content+=`<div class="filters">${state.view==='artist'?'<button class="chip" data-view="artists" aria-label="Back to all artists">← Every artist</button>':''}<button class="chip ${!state.genre?'active':''}" data-genre="">All sounds</button>${genres.slice(0,4).map(g=>`<button class="chip ${state.genre===g?'active':''}" data-genre="${esc(g)}">${esc(g)}</button>`).join('')}<select id="genre-filter" aria-label="Filter by genre"><option value="">Every genre</option>${genres.map(g=>`<option ${g===state.genre?'selected':''}>${esc(g)}</option>`).join('')}</select><select id="sort" aria-label="Sort tracks">${[['youtube',state.view.startsWith('source:')&&!state.config.sources.find(s=>'source:'+s.id===state.view)?.playlist?'Source order':state.config.sources.some(s=>s.playlist)?'Playlist order':'Library order'],['title','Title A–Z'],['artist','Artist A–Z'],['added','Recently added'],['recent','Recently played'],['plays','Most played'],['duration','Longest first']].map(([v,l])=>`<option value="${v}" ${state.sort===v?'selected':''}>${l}</option>`).join('')}</select></div>${state.sort==='youtube'&&state.config.sources.some(s=>s.playlist)&&!(state.view.startsWith('source:')&&!state.config.sources.find(s=>'source:'+s.id===state.view)?.playlist)?`<p class="playlist-order-note fine-print">Playlist order · saved on this computer. Original playlist numbers are shown; music without a match follows at the end. <button class="text-button" data-action="sync">Refresh order ↗</button></p>`:''}${table(ts)}`;if(ts.length>state.limit)content+=`<div class="load-more"><button class="secondary" data-action="more">Show more · ${state.limit} of ${ts.length}</button></div>`;}
  $('#main').innerHTML=content;
}
function renderSettings(){const sources=state.config.sources;const matched=state.tracks.filter(t=>t.artwork).length;const listens=state.tracks.reduce((s,t)=>s+t.plays,0);$('#main').innerHTML=`<div class="page-heading"><div><div class="eyebrow">MAKE YOURSELF AT HOME</div><h1>Settings & library</h1><p>Everything you love, kept close.</p></div></div>${storageCard()}${listeningSettings(state.prefs)}${sourceUI.settingsCard()}<div class="settings-card"><h2>Make every track feel complete</h2><button class="secondary" data-action="review-metadata">Review missing & uncertain details</button><p>Use your YouTube playlists to recover original artwork and source details. MusicBrainz adds matched artists, albums, release dates, and genres. Your edits are always preserved.</p><div class="setting-row"><div><h3>${matched.toLocaleString()} artworks stored locally</h3><p>${state.tracks.length.toLocaleString()} files · ${listens.toLocaleString()} plays · ${humanHours(state.tracks.reduce((s,t)=>s+(t.listenedSeconds||0),0))} listened</p></div><button class="secondary" data-action="sync">Update playlists</button></div><div class="setting-row"><div><h3>Artist & release matching</h3><p id="enrich-status">Only confident matches are applied automatically. Other matches can be reviewed in track details.</p></div><button class="secondary" data-action="enrich">${state.status.enrich?.running?'Pause matching':'Find metadata'}</button></div></div><div class="settings-card"><h2>Sound, as it is</h2><p>Files play directly from disk. Equalization is off by default. Output follows your Windows audio device and may be resampled by the audio engine. A FLAC file can contain audio previously converted from a lossy source.</p><div class="setting-row"><div><h3>New download format</h3><p>Original quality keeps the best YouTube audio without another lossy encode. FLAC is larger and cannot restore missing detail.</p></div><select id="download-format"><option value="best" ${state.config.downloadFormat==='best'?'selected':''}>Original quality</option><option value="flac" ${state.config.downloadFormat==='flac'?'selected':''}>FLAC</option></select></div></div><div class="settings-card"><h2>Good to know</h2><h3>Mouse gestures</h3><p>Hold the left mouse button on the background and drag to orbit the sculpture. Visual settings offers a Rollercoaster rail and Reset view.</p><p>On the background or over Sona, scroll up / down for volume. Hold Shift for fine adjustment.</p><p>Hold the right mouse button and drag right / left for the next / previous song. Drag up / down to seek forward / back; hold Shift for finer seeking. Release to finish. Left-click while holding the right button, or press Escape, to cancel.</p><p>Click the volume percentage for an exact value. Click outside Library or Visual settings to close them.</p><h3 style="margin-top:20px">Keyboard shortcuts</h3><p>Space: play / pause · L: library · Q: queue · H: immerse · F11: fullscreen · Ctrl K: search · Alt → / ←: next / previous · Escape: close a panel</p><p style="margin-top:12px">A play counts after 30 seconds of listening, or half a shorter track. Skipping ahead does not count as listening. Long mixes remember where you stopped. Dates and global YouTube views are shown only when available; your local plays are counted separately.</p><p style="margin-top:12px">Database, thumbnails, matches and download archive are stored in this app’s data folder. The original audio files are never retagged by metadata matching.</p><p style="margin-top:12px">Metadata: <a href="https://musicbrainz.org" target="_blank" rel="noreferrer">MusicBrainz</a> · Artwork: Cover Art Archive / original YouTube thumbnails · Downloads: yt-dlp.</p></div>`;}
function renderNow(){atmosphere.select(state.current,state.session);void artworkPalette.select(state.current?.artwork||null);immersive.updateTrack();if($('#dialog').open&&state.dialog==='The next chapter'&&(state.queuePaintCursor!==playQueue.cursor||state.queuePaintId!==state.current?.id)){queueDialog();}const t=state.current;$('#now-art').innerHTML=art(t);$('#mini-art').innerHTML=art(t);$('#now-title').textContent=t?.title||'Find your frequency';$('#now-artist').textContent=t?.artist||t?.channel||'Choose something that moves you.';$('#mini-title').textContent=t?.title||'Nothing playing yet';$('#mini-artist').textContent=t?.artist||t?.channel||'Your next favorite is in here.';$('#now-quality').textContent=t?quality(t):'Local playback · no subscription';$('#now-favorite').classList.toggle('active',!!t?.favorite);$('#now-favorite').setAttribute('aria-pressed',String(!!t?.favorite));$('#room-title').textContent=t?.title||'Let the music begin.';$('#room-artist').textContent=t?.artist||t?.channel||'Press play. Let everything else fade.';const idx=playQueue.cursor;const next=playQueue.items.slice(idx+1,idx+4).map(getTrack).filter(Boolean);$('#up-next').innerHTML=next.map((t,i)=>`<button class="queue-mini" data-play="${t.id}" data-from-queue="true" data-queue-index="${idx+1+i}"><div>${art(t)}</div><span><b>${esc(t.title)}</b><small>${esc(t.artist||t.channel||'Your collection')}</small></span><time>${duration(t.duration)}</time></button>`).join('')||'<p class="fine-print" style="margin-bottom:25px">Let a track lead you somewhere.</p>';updateSystemMedia();}
function shuffled(array){const a=[...array];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
async function flush(){if(!state.current||!state.session)return;const id=state.current.id,session=state.session,seconds=state.pendingSeconds;state.pendingSeconds=0;const stats=await api('/api/listen',{id,session,seconds,position:audio.currentTime||0}).catch(()=>null);if(stats?.track){const t=getTrack(id);if(t)Object.assign(t,stats.track);if(state.current?.id===id)state.current=t;}await savePlayer();}
async function savePlayer(){if(!state.current)return;return api('/api/player',{id:state.current.id,position:audio.currentTime||0,volume:audio.volume,...playQueue.snapshot()}).catch(()=>{});}
async function playTrack(id,ids,autoplay=true,restorePosition,queueIndex,fadeSeconds=0){
  const t=getTrack(id);if(!t?.available){toast('This file is unavailable. Reconnect its drive and rescan.');return;}
  desktopAudio.stop();const generation=++state.playGeneration;await flush();if(generation!==state.playGeneration)return;
  if(fadeSeconds)await listening.beginFade(fadeSeconds);else listening.cancelFade();if(generation!==state.playGeneration||fadeSeconds&&!state.wantsPlayback){listening.cancelFade();return;}
  audio.pause();state.current=getTrack(id)||t;state.session=crypto.randomUUID();state.pendingSeconds=0;state.lastTick=0;state.wantsPlayback=autoplay;
  if(ids){playQueue.start(id,ids,state.shuffle);state.playFailures=0;}else playQueue.select(id,queueIndex);
  await listening.select(state.current);if(generation!==state.playGeneration)return;reactor.resetAnalysis();audio.src='/audio/'+id;
  if(state.loadHandler)audio.removeEventListener('loadedmetadata',state.loadHandler);
  const resume=restorePosition??(t.kind==='mix'&&t.position>10&&t.position<t.duration-15?t.position:0);
  state.loadHandler=()=>{if(generation!==state.playGeneration)return;const start=Math.max(resume,listening.range().start);if(start)audio.currentTime=Math.min(start,Math.max(0,audio.duration-1));};
  audio.addEventListener('loadedmetadata',state.loadHandler,{once:true});audio.load();renderNow();
  $$('.track-table tr').forEach(r=>r.classList.toggle('playing',r.querySelector('[data-play]')?.dataset.play===id));
  if(autoplay){await reactor.connect();if(generation!==state.playGeneration)return;reactor.eq(state.eq);try{await audio.play();}catch(e){if(generation===state.playGeneration&&e.name!=='AbortError'){if(e.name==='NotAllowedError')toast('Press Play to start listening.');else await failedPlayback(generation);}}}
  if(generation===state.playGeneration){if(autoplay&&!audio.paused)listening.finishFade(fadeSeconds);else listening.cancelFade();savePlayer();}
}
async function failedPlayback(generation=state.playGeneration){
  if(generation!==state.playGeneration||state.failedGeneration===generation||!state.current)return;state.failedGeneration=generation;
  if(!state.wantsPlayback){toast('This audio file could not be opened. Check its drive.');return;}
  playQueue.failed.add(state.current.id);state.playFailures=(state.playFailures||0)+1;
  if(state.playFailures>=5||playQueue.next()===null){audio.pause();state.wantsPlayback=false;toast('Playback paused: the next files could not be opened. Check that your music drive is connected.');renderNow();return;}
  toast('Skipping an unavailable file.');await nextTrack();
}
async function togglePlay(){if(desktopAudio.state!=='off'){desktopControlNotice();return;}if(!state.current){const ts=filtered();if(ts[0])return playTrack(ts[0].id,ts.map(t=>t.id));closeRoom();if(!state.config.sources.length)sourceUI.openForm();return;}if(audio.paused){state.wantsPlayback=true;state.playFailures=0;playQueue.failed.clear();playQueue.ensure();renderNow();const generation=++state.playGeneration;await reactor.connect();if(generation!==state.playGeneration||desktopAudio.state!=='off')return;await audio.play();}else{state.wantsPlayback=false;audio.pause();await flush();}}
async function nextTrack(direction=1,ended=false,forceSkip=false,fadeSeconds=0){
  if(desktopAudio.state!=='off'){if(!ended)desktopControlNotice();return;}
  if(!state.current)return togglePlay();if(direction===-1&&!forceSkip&&audio.currentTime>3){audio.currentTime=0;return;}
  if(ended&&state.repeat===2)return playTrack(state.current.id,undefined,true,0,playQueue.cursor);
  const index=playQueue.next(direction);if(index===null){if(direction<0){audio.currentTime=0;return;}audio.pause();return;}
  await playTrack(playQueue.items[index],undefined,true,0,index,fadeSeconds);
}
