function details(id){const t=getTrack(id);if(!t)return;state.detailId=id;showDialog('Behind the sound','Your file, its story, and the details worth keeping.',`<div class="detail-intro"><div>${art(t)}</div><div><span class="eyebrow">${esc(t.kind==='mix'?'LONG MIX':'LOCAL TRACK')}</span><h3>${esc(t.title)}</h3><p>${esc(t.artist||t.channel||'Artist unknown')}</p><span class="format-pill">${esc(quality(t))}</span><span class="format-pill">${duration(t.duration)}</span></div></div><div class="detail-stats"><div><b>${t.plays}</b><small>Your plays</small></div><div><b>${humanHours(t.listenedSeconds||0)}</b><small>Time together</small></div><div><b>${t.views?Number(t.views).toLocaleString():'—'}</b><small>YouTube views · snapshot</small></div><div><b>${t.date?esc(t.date.slice(0,4)):'—'}</b><small>Release year</small></div></div>${t.channel?`<p class="fine-print">Uploaded by ${esc(t.channel)}</p>`:""}<p class="fine-print">Artists: ${artistNames(t).map(esc).join(" · ")||"To discover"}</p>${listeningEditMarkup()}${searchPanel(t,esc)}${songStory(t,state.tracks,{esc,art,icon})}<details class="song-edit"><summary>Metadata, files & editing</summary><form id="metadata-form"><div class="field-grid">${[['title','Title'],['artist','Artist'],['album','Album'],['genre','Genre'],['date','Release date']].map(([k,l])=>`<label class="field">${l}<input name="${k}" value="${esc(t[k])}" ${k==='title'?'required':''}></label>`).join('')}</div><button type="submit" class="secondary">Save your edits</button></form>${genreDetails(t)}<div class="details-source"><p class="fine-print">Metadata: ${esc(t.metadataSource)} · ${esc(t.metadataStatus)}${t.metadataUrl?` · <a href="${esc(t.metadataUrl)}" target="_blank" rel="noreferrer">View recording ↗</a>`:''}<br>${t.sourceUrl?`<a href="${esc(t.sourceUrl)}" target="_blank" rel="noreferrer">Original YouTube source ↗</a>`:''}${t.spotifyUrl?` · <a href="${esc(t.spotifyUrl)}" target="_blank" rel="noreferrer">Spotify playlist match ↗</a>`:''}${t.uploadDate?` · Uploaded ${esc(t.uploadDate)}`:''}<br>${esc(t.path)}<br>${(t.size/1e6).toFixed(1)} MB · ${t.available?'Available on disk':'File unavailable'}${t.kind==='mix'&&t.position?` · Resume at ${duration(t.position)}`:''}</p>${t.youtubeId?`<button class="secondary" style="margin-top:12px" data-source-refresh="${t.id}">Refresh upload date & YouTube details</button>`:''}</div></details>`,`<button class="secondary" data-queue-add="${id}">${icon('queue')} Add to queue</button><button class="secondary" data-add-playlist="${id}">${icon('plus')} Add to playlist</button><button class="primary" data-play="${id}">${icon('play')} Play now</button>`);mountListeningEdit({container:$('#dialog-content'),track:t,audio,current:()=>state.current,play:(id,start)=>playTrack(id,undefined,true,start),request:(action,data)=>action==='get'?api('/api/audio-profile?id='+encodeURIComponent(id)):api(action==='edit'?'/api/playback-edit':'/api/audio-profile',{...data,force:true}),onChange:()=>{if(state.current?.id===id)void listening.select(state.current);}});fillSongStory(id,{api,esc,track:t,container:$('#dialog-content'),onSaved:async()=>{await refresh(false);if(state.detailId===id&&state.dialog==='Behind the sound')details(id);}});}
function playlistDialog(trackId='',editing=false){const playlist=editing?state.playlists.find(p=>`playlist:${p.id}`===state.view):null;state.addTrackId=trackId;state.editPlaylistId=playlist?.id;showDialog(playlist?'Edit playlist':trackId?'Save to a playlist':'A home for a mood',trackId?'Keep this sound close.':'Give this collection a name.',`${trackId?state.playlists.map(p=>`<button class="setting-row" style="width:100%;text-align:left" data-add-existing="${p.id}"><span>${esc(p.name)}</span><small>${p.tracks.length} tracks ${icon('plus')}</small></button>`).join(''):''}<form id="playlist-form"><label class="field">${playlist?'Playlist name':'Create a new playlist'}<input name="name" required maxlength="100" placeholder="Late night signals" value="${esc(playlist?.name||'')}"></label><button class="primary" type="submit">${playlist?'Save name':trackId?'Create & add track':'Create playlist'}</button></form>${playlist?`<div style="margin-top:20px">${playlist.tracks.map(id=>{const t=getTrack(id);return t?`<div class="queue-row"><span style="flex:1;font-size:12px">${esc(t.title)}</span><button class="icon-button" data-remove-playlist-track="${id}" aria-label="Remove ${esc(t.title)} from playlist">${icon('close')}</button></div>`:'';}).join('')}</div><button class="danger" data-action="delete-playlist" style="margin-top:20px">Delete this playlist</button>`:''}`);}
function queueDialog(tab=state.queueTab||'next'){
  if(typeof tab!=='string')tab=state.queueTab||'next';
  const dialog=$('#dialog'),wasOpen=dialog.open&&state.dialog==='The next chapter',oldBody=dialog.querySelector('.dialog-body');
  state.queueScroll??={};if(wasOpen&&oldBody)state.queueScroll[state.queueTab||'next']=oldBody.scrollTop;
  const active=document.activeElement,focusAttrs=wasOpen&&dialog.contains(active)?[...active.attributes].filter(a=>a.name.startsWith('data-')).map(a=>[a.name,a.value]):[];
  state.queueTab=tab;dialog.dataset.panel='queue';state.queuePaintCursor=playQueue.cursor;state.queuePaintId=state.current?.id;
  const remaining=Math.max(0,playQueue.items.length-playQueue.cursor-1),history=playQueue.history.filter(e=>e.session!==state.session).slice().reverse();
  let body='';
  if(tab==='history'){
    body='<p class="fine-print queue-explainer">Songs you actually listened to, newest first. Replay one without losing what comes next. Your last 200 starts are saved on this computer.</p>'+(history.some(e=>e.session.startsWith('earlier-'))?'<p class="fine-print queue-explainer">Earlier listening was recovered from your library: the last known play of each song.</p>':'')+'';
    body+=history.map(e=>{const t=getTrack(e.id);if(!t)return '';return '<div class="queue-row history-row"><button class="queue-mini" data-history-play="'+e.id+'" data-history-session="'+esc(e.session)+'" '+(!t.available?'disabled':'')+'><div>'+art(t)+'</div><span><b>'+esc(t.title)+'</b><small>'+esc(t.artist||t.channel||'Your collection')+(!t.available?' · File unavailable':'')+'</small></span><time title="'+esc(new Date(e.at).toLocaleString())+'">'+esc(new Date(e.at).toLocaleDateString([],{month:'short',day:'numeric'})+' · '+new Date(e.at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}))+'</time></button></div>';}).join('');
    if(!history.length)body+='<div class="empty-state"><h2>Your listening trail begins here.</h2><p>Once you move to another song, the ones you played will appear here.</p></div>';
  }else if(state.current){
    body='<p class="queue-continuity">∞ Continuous listening <span>Your chosen order plays first. More music follows automatically.</span></p>'+playQueue.items.slice(playQueue.cursor,playQueue.cursor+81).map((id,offset)=>{
      const i=playQueue.cursor+offset,t=getTrack(id);if(!t)return '';return '<div class="queue-row"><button class="queue-mini" data-play="'+id+'" data-from-queue="true" data-queue-index="'+i+'"><div>'+art(t)+'</div><span><b>'+(offset===0?'♫ ':'')+esc(t.title)+'</b><small>'+esc(t.artist||t.channel||'Your collection')+'</small></span><time>'+duration(t.duration)+'</time></button>'+(offset?'<button class="icon-button" data-queue-move="'+i+':-1" aria-label="Move '+esc(t.title)+' up" '+(offset===1?'disabled':'')+'>'+icon('up')+'</button><button class="icon-button" data-queue-move="'+i+':1" aria-label="Move '+esc(t.title)+' down">'+icon('down')+'</button><button class="icon-button" data-queue-remove="'+i+'" aria-label="Remove '+esc(t.title)+' from queue">'+icon('close')+'</button>':'<span class="format-pill">'+(desktopAudio.state==='off'?'NOW':'PAUSED')+'</span>')+'</div>';
    }).join('')+(remaining>80?'<p class="fine-print">Showing the next 80 of '+remaining+' tracks.</p>':'');
  }else body='<div class="empty-state"><h2>Let the music lead.</h2><p>Click any track to build a continuing queue.</p></div>';
  showDialog('The next chapter',desktopAudio.state!=='off'?'Local queue paused · choose a song to leave desktop audio':state.current?remaining+' queued · keeps playing automatically':'Start with any track',body);
  const tabs='<div class="queue-tabs" role="group" aria-label="Queue view">'+[['next','Up next'],['history','Played before']].map(([id,label])=>'<button class="chip" data-queue-tab="'+id+'" aria-pressed="'+(id===tab)+'">'+label+'</button>').join('')+'</div>';
  dialog.querySelector('.dialog-heading').insertAdjacentHTML('afterend',tabs);
  const scroller=dialog.querySelector('.dialog-body');scroller.tabIndex=0;scroller.setAttribute('aria-label',tab==='history'?'Played tracks':'Upcoming tracks');
  if(focusAttrs.length){const selector=focusAttrs.map(([name,value])=>'['+name+'="'+CSS.escape(value)+'"]').join('');(dialog.querySelector(selector)||dialog.querySelector('[data-queue-tab="'+tab+'"]'))?.focus({preventScroll:true});}
  scroller.scrollTop=state.queueScroll[tab]||0;
}
function reviewMetadata(){const tracks=state.tracks.filter(t=>t.available&&reviewReasons(t).length);showDialog('Library review',tracks.length+' songs with details worth checking. Your edits are protected.', '<div class="metadata-review-list">'+tracks.slice(0,150).map(t=>'<button class="secondary" data-detail="'+esc(t.id)+'"><b>'+esc(t.title)+'</b><small>'+esc(t.artist||'Unknown artist')+' · '+esc(reviewReasons(t).join(' · '))+'</small></button>').join('')+'</div>'+(tracks.length>150?'<p class="fine-print">Showing the first 150. Reopen after reviewing these to see more.</p>':!tracks.length?'<p>No missing or uncertain fields found.</p>':''));}
