  if(state.prefs.responseDesignVersion!==1)await setPreferences({responsiveness:state.prefs.responsiveness??DEFAULT_PREFERENCES.responsiveness,responseDesignVersion:1});
  if(state.prefs.colorDesignVersion!==2)await setPreferences({coverPalette:true,particleColor:'palette',colorDesignVersion:2});
  boot?.stage('Setting the room for your music');
  renderMain();await yieldSceneWork();
  audio.volume=d.session?.volume??.7;listeningControls.sync();$('#volume').value=audio.volume;$('#volume').style.setProperty('--progress',audio.volume*100+'%');
  if(d.session?.id&&getTrack(d.session.id)?.available){playQueue.restore(d.session);await playTrack(d.session.id,undefined,false,d.session.position||0);}
  await yieldSceneWork();openRoom();if(!state.config.sources.length)closeRoom();
