  boot?.prepareReveal();await yieldSceneWork();
  if(!reactor.musicOnly){boot?.stage('Preparing your display');await preflightHDROutput(reactor.hdrMode||'auto');}
  reactor.prepareGraphics();await yieldSceneWork();
  boot?.animate();await yieldSceneWork();
  boot?.stage('Preparing light and color');
