function feedbackSettings(){return `<div class="feedback-settings">${state.prefs.musicOnly?'<p class="notice">Interface sounds and motion are resting in Music only mode. Your preferences will return with the visualizer.</p>':''}<div class="setting-row"><div><h3>A little music in every touch</h3><p>Glassy hover notes, textured plucks, rising navigation phrases and a blooming chord for favorites. Automatically quieter during playback.</p></div><label class="toggle-label"><input type="checkbox" data-preference="sfx" ${state.prefs.sfx!==false?'checked':''}> Interface sounds</label></div><div class="setting-row"><label class="sound-level">Sound level <input type="range" min="0" max="1" step=".05" value="${feedback.volume}" data-preference="sfxVolume" aria-label="Interface sound volume"></label><button class="secondary" data-action="sfx-test">Hear a preview</button></div></div>`;}
function appendPreferences(){$('#main').insertAdjacentHTML('beforeend',`<div class="settings-card">${visualSyncMarkup(state.prefs)}</div><div class="settings-card"><h2>Feel every interaction</h2>${feedbackSettings()}<div class="setting-row"><div><h3>Movement & light</h3><p>Hover halos, click ripples, gentle page transitions, and animated visual scenes.</p></div><label class="toggle-label"><input type="checkbox" data-preference="motion" ${state.prefs.motion!==false?'checked':''}> Motion</label></div></div><div class="settings-card"><h2>A richer map of your music</h2><p>Find genre labels for the music already in your library and save them on this computer. This does not download music. Recording and release labels come first, including exact catalogue matches. Artist suggestions from MusicBrainz and Wikidata are marked ≈. Uncertain matches stay unlabelled.</p><div class="setting-row"><div><h3>Genre discovery</h3><p data-genre-progress role="status" aria-live="polite">Saved locally, including evidence and lookup cache.</p></div><button class="secondary" data-action="genres">${state.status.genres?.running?'Pause discovery':'Discover genres'}</button></div><button class="text-button" data-view="genres">Explore your genres ↗</button></div>`);updateGenreProgress(state.status.genres);}
function updateGenreProgress(job){if(!job)return;for(const b of $$('[data-action=genres]')){b.textContent=job.running?(job.stop?'Pausing…':'Pause discovery'):job.phase==='complete'?'Retry missing genres':job.phase==='paused'?'Resume discovery':'Discover genres';b.disabled=!!job.running&&!!job.stop;}for(const e of $$('[data-genre-progress]'))e.textContent=job.running?`${job.stop?'Pausing after this lookup':job.phase==='artists'?'Exploring artists':'Looking deeper per track'} · ${job.done} / ${job.total} · ${job.found||0} tracks gained genres · ${job.message}`:job.phase==='paused'?`Paused · ${job.done} lookups complete. ${job.lastError||'Your progress is saved.'}`:job.phase==='complete'?job.message:'Source labels, recordings, releases and artist catalogues. Results and sources stay on your computer.';for(const e of $$('[data-genre-coverage]'))e.textContent=state.tracks.filter(t=>t.available&&t.genre).length.toLocaleString();updateGenreCards();}
function genreCard(name,count,i){return `<button class="genre-card" data-genre="${esc(name)}" style="--genre-hue:${(245+i*31)%360}"><span class="genre-art" aria-hidden="true"><i></i><i></i><i></i><i></i></span><span class="genre-index">${String(i+1).padStart(2,'0')}</span><span class="genre-card-name">${esc(name)}</span><span class="genre-card-count">${count} sounds <b>↗</b></span></button>`;}
function updateGenreCards(){
 const grid=$('.genre-grid');if(!grid)return;const counts=genreCounts(),map=new Map(counts);
 for(const card of grid.querySelectorAll('[data-genre]')){if(card.dataset.genre==='__unknown')continue;const count=map.get(card.dataset.genre)||0;card.querySelector('.genre-card-count').innerHTML=count+' sounds <b>↗</b>';map.delete(card.dataset.genre);}
 const unknown=grid.querySelector('.genre-unknown');let i=counts.length;for(const [name,count]of map)unknown.insertAdjacentHTML('beforebegin',genreCard(name,count,i++));
 const all=state.tracks.filter(t=>t.available),known=all.filter(t=>t.genre),suggested=known.filter(t=>t.genreBasis==='artist');unknown.querySelector('.genre-card-count').innerHTML=(all.length-known.length)+' sounds <b>↗</b>';
 const summary=$('.genre-toolbar>.fine-print');if(summary)summary.textContent=counts.length+' genres · '+(known.length-suggested.length)+' track labels · '+suggested.length+' artist-based suggestions (≈)';const bar=$('.genre-progress-track i');if(bar)bar.style.width=known.length/Math.max(1,all.length)*100+'%';
}
function renderGenres(){
 const all=state.tracks.filter(t=>t.available),known=all.filter(t=>t.genre),suggested=known.filter(t=>t.genreBasis==='artist'),counts=genreCounts(),selected=state.genre;
 $('#breadcrumb').textContent=selected==='__unknown'?'Still to discover':selected||'Explore genres';
 let html=`<div class="page-heading"><div><div class="eyebrow">FOLLOW A FEELING</div><h1>${esc(selected==='__unknown'?'Still to discover':selected||'A spectrum of sound.')}</h1><p>${selected?'Your collection, tuned to this frequency.':'Different colors. Different worlds. All your music.'}</p></div><button class="secondary" data-action="genres">${state.status.genres?.running?'Pause discovery':'Discover genres'}</button></div>`;
 if(selected){html+=`<div class="filters"><button class="chip" data-genre="">← Every genre</button><button class="primary" data-action="play-all">${icon('play')} Play this feeling</button><span class="fine-print">${filtered().length} tracks</span></div>${table(filtered())}${filtered().length>state.limit?'<div class="load-more"><button class="secondary" data-action="more">Show more tracks</button></div>':''}`;}
 else{
 html+=`<section class="genre-banner"><div><span class="eyebrow">YOUR COLLECTION, COMING INTO COLOR</span><h2><span data-genre-coverage>${known.length.toLocaleString()}</span><small> / ${all.length.toLocaleString()} sounds with a genre</small></h2><p data-genre-progress role="status" aria-live="polite">Recording, release, and artist evidence, saved on your computer.</p><div class="genre-progress-track"><i style="width:${known.length/Math.max(1,all.length)*100}%"></i></div></div><div class="genre-orbits" aria-hidden="true"><i></i><i></i><i></i></div></section><div class="genre-toolbar"><p class="fine-print">${counts.length} genres · ${known.length-suggested.length} track labels · ${suggested.length} artist-based suggestions (≈)</p><label class="toggle-label"><input type="checkbox" data-preference="artistGenres" ${state.prefs.artistGenres!==false?'checked':''}> Include artist suggestions</label></div><div class="genre-grid">${counts.map(([name,count],i)=>genreCard(name,count,i)).join('')}<button class="genre-card genre-unknown" data-genre="__unknown"><span class="genre-index">KEEP EXPLORING</span><span class="genre-card-name">Still to discover</span><span class="genre-card-count">${all.length-known.length} sounds <b>↗</b></span></button></div><p class="fine-print">Genre discovery is gradual and can be paused. Results and provider responses are cached locally. Your own genre edits take priority. ≈ means an artist suggestion; a song may have a different style.</p>`;
 }$('#main').innerHTML=html;updateGenreProgress(state.status.genres);
}
function genreDetails(t){const evidence=t.genreEvidence||[];return `<section class="genre-evidence"><div class="section-heading"><div><h2>The color of this sound</h2><p>${t.genreLocked?'Your genre edit is protected.':t.genreBasis==='artist'?'Suggested from the artist. This recording may differ.':'Recording, release, and source evidence.'}</p></div></div><div class="evidence-tags">${evidence.map(e=>`<span class="evidence-tag"><b>${e.scope==='artist'?'≈ ':''}${esc(e.name)}</b><small>${esc(e.scope)} · ${e.url?`<a href="${esc(e.url)}" target="_blank" rel="noreferrer">${esc(e.source)} ↗</a>`:esc(e.source)}</small></span>`).join('')||'<p class="fine-print">No genre evidence yet. Try a deeper lookup or enter your own genre above.</p>'}</div><button class="secondary" data-genre-track="${t.id}" ${t.genreLocked?'data-unlock="true"':''}>${t.genreLocked?'Use discovered genres instead':'Search genres for this track'}</button>${t.genreCheckedAt?`<p class="fine-print">Last checked ${new Date(t.genreCheckedAt).toLocaleString()} · saved locally</p>`:''}${t.genreError?`<p class="fine-print">Last lookup: ${esc(t.genreError)}</p>`:''}</section>`;}
$('#audio-meters').innerHTML=BANDS.map((b,i)=>`<div class="frequency-meter"><div class="meter-track" data-band="${i}" role="meter" aria-label="${b.name} ${b.label}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><i></i></div><b>${b.name}</b><small>${b.label}</small></div>`).join('')+'<div class="loudness-readout"><b><span id="rms-value">−∞</span><small>RMS · dBFS</small></b><b><span id="peak-value">−∞</span><small>PEAK · dBFS</small></b></div>';
$('#visual-quality').onchange=safe(e=>setPreferences({quality:e.target.value}));
$('#room-sound').onclick=soundDialog;
$('.brand[href]').addEventListener('click',e=>{e.preventDefault();navigate('home');});
window.resonancePrepareClose=async()=>{desktopAudio.stop();audio.pause();await flush();};
const displaySettings=installDisplaySettings({reactor});
const visualSyncUI=installVisualSyncUI({reactor,state,setPreferences,onError:toast});
const syncReview=installSyncReview({entries:()=>state.syncPreview?.entries||[],getTrack,esc,duration});
const sourceUI=installSourceUI({state,api,esc,icon,showDialog,closeDialog,refresh,navigate,closeRoom,toast});
const immersive=installImmersiveUI({audio,state,icon,safe,togglePlay,nextTrack,queueDialog,soundDialog,openRoom,closeRoom,closeDialog,savePlayer,details});
installBrand();installPortableUpdateUI({toast,state});
const atmosphere=installAtmosphereUI({state,reactor,api,setPreferences,toast});
installSonaDesktop({state,reactor,audio,togglePlay,nextTrack,setPreferences,toast});
installWindowUI({button:$('#fullscreen'),onError:e=>toast('Fullscreen unavailable: '+e.message)});
const desktopAudio=new DesktopAudio({reactor,audio,bridge:window.resonanceDesktop,mediaDevices:navigator.mediaDevices,beforeStart:async()=>{if(state.prefs.musicOnly)await setPreferences({musicOnly:false});},onChange:status=>{
 if(status==='starting')state.playGeneration++;if(status==='listening'){state.wantsPlayback=false;void flush();}
 const active=status!=='off',starting=status==='starting';document.body.classList.toggle('desktop-listening',active);$('.desktop-audio-dock').hidden=!active;$('.room-dock').inert=active;
 $('#desktop-audio').setAttribute('aria-pressed',String(active));$('#desktop-audio').textContent=starting?'Cancel connection':active?'Stop listening':'Desktop audio';$('#desktop-audio').setAttribute('aria-label',starting?'Cancel desktop audio connection':active?'Stop listening to desktop audio':'Listen to desktop audio');
 $('#desktop-audio-status').textContent=starting?'Connecting to desktop audio…':'Listening to desktop audio';$('#stop-desktop-audio').textContent=starting?'Cancel':'Stop listening';$('#resume-library-audio').hidden=!state.current?.available;$('#resume-library-audio').disabled=starting;$('#music-only').disabled=starting;
 feedback.desktopListening=active;listeningControls?.closeVolume();updateSystemMedia();applyInterfaceAccent(active?null:reactor.coverColors,state.prefs.coverInterface!==false);atmosphere.identityStatus();
 if(status==='off'&&document.activeElement?.closest('.desktop-audio-dock'))$('#desktop-audio').focus();
}});
$('#desktop-audio').onclick=safe(async()=>{if(desktopAudio.state!=='off'){desktopAudio.stop();return;}await desktopAudio.start();});
$('#stop-desktop-audio').onclick=()=>desktopAudio.stop();
$('#resume-library-audio').onclick=safe(async()=>{desktopAudio.stop();await togglePlay();});
$('#desktop-queue').onclick=queueDialog;
window.addEventListener('pagehide',()=>desktopAudio.stop());
const listeningControls=installListeningControls({isDesktop:()=>desktopAudio.state!=='off',audio,savePlayer,nextTrack,safe,libraryOpen:immersive.libraryOpen,icon});
function applyMusicOnly(){const enabled=!!state.prefs.musicOnly;if(enabled)desktopAudio.stop();document.body.classList.toggle('music-only',enabled);$('#music-only').setAttribute('aria-pressed',String(enabled));$('#music-only').textContent=enabled?'Show visualizer':'Music only';$('#music-only').title=enabled?'Return to live visuals':'Stop graphics and analysis; keep the original audio';if(enabled&&document.body.classList.contains('cinema'))setCinema(false);reactor.setMusicOnly(enabled);void artworkPalette.select(state.current?.artwork);immersive.updateTrack();}
$('#music-only').onclick=safe(()=>setPreferences({musicOnly:!state.prefs.musicOnly}));
$('#music-cover-play').onclick=safe(togglePlay);
init();
